// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Roulette c;

    function setUp() public {
        vm.deal(address(this), 10 ether);
        c = new Roulette{value: 10 ether}();
    }

    function _run(uint256 amount) internal {
        vm.assume(amount >= 0);
        uint256 pbt1;
        try c.pastBlockTime() returns (uint256 __r) { pbt1 = __r; } catch { return; }
        uint256 pbt2;
        try c.pastBlockTime() returns (uint256 __r) { pbt2 = __r; } catch { return; }
        assertTrue(pbt1 == pbt2 && pbt1 <= block.timestamp + 1);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
